TRANSLATIONS_SLICE1 = {
    'STm10001_01.4': 'Hồi 1',
    'STm10001_01.5': 'Dĩ Vãng Tái Hiện',
    'STm10001_01.6': 'Sau quãng thời gian đằng đẵng bị giam cầm trong Phòng Trắng, bạn một lần nữa tỉnh giấc từ Hộp Ước Nguyện và nhìn thấy hai gương mặt vừa quen thuộc lại vừa xa lạ. Bạn bất đắc dĩ vào vai một Tu Giả Tập Sự, nhưng không thể nào qua mắt được ánh nhìn dò xét sắc bén của cô ấy…',
    'STm10001_01.44': 'Vĩnh biệt. Giờ thì... hãy hòa làm một với ta, và trở thành nền móng cho thế giới mới!',
    'STm10001_01.74': 'Sếp ơi. Có phải chúng ta... sắp chết rồi không?',
    'STm10001_01.81': 'Được ngồi bên cạnh Sếp thế này... rồi hóa thành ngọn hải đăng dẫn lối cho những Lữ Khách khác... Ra đi như thế này cũng không tệ chút nào, Sếp nhỉ.',
    'STm10001_01.87': 'Sếp, tỉnh lại đi! Mở mắt ra nhìn em này! Vẫn còn bao nhiêu cảnh đẹp trên thế gian này chúng ta chưa được nhìn thấy cơ mà!',
    'STm10001_01.105': 'Thế nên xin người, Bạo Chúa của em, đừng một lần nữa tan biến hóa thành những vì sao.',
    'STm10001_01.107': 'Con đường mòn cũ kỹ rồi sẽ lại dẫn tới những kết cục bi thương quen thuộc mà thôi.',
    'STm10001_01.110': 'CH10001Intro1/CH10001Intro1',
    'STm10001_01.112': '<size=60>♪</size>~==W==<size=60>♪</size>~==W==<size=60>♫</size>~==W==<size=60>♫</size>~==W==<size=60>♪</size>~==W==<size=60>♪</size>~==W==<size=60>♫</size>~==W==<size=60>♫</size>~',
    'STm10001_01.117': 'Hửm? Giọng nói này... Chẳng phải là từ hồi đó sao?',
    'STm10001_01.119': 'Mình đã quay ngược thời gian rồi ư?==RT==Quay về khoảnh khắc Lữ Đoàn Tân Tinh lần đầu tiên tìm thấy mình sao?!',
    'STm10001_01.121': '==Off==<color=black><size=70>Mình đã có thêm một cơ hội nữa!',
    'STm10001_01.126': 'Mở mắt ra',
    'STm10001_01.131': 'CH10001Intro2/CH10001Intro2',
    'STm10001_01.141': 'Chủ nhân!==W== Cuối cùng người cũng tỉnh lại rồi!',
    'STm10001_01.150': 'Có vẻ như bạn đồng hành của ngươi đã tỉnh giấc rồi đấy.',
    'STm10001_01.157': 'Iris... Noya... Thật may quá, lại được gặp hai người rồi.',
    'STm10001_01.162': 'Iris? Noya? Nghe đây hả kẻ tội đồ. Chẳng có cái tên nào trùng với cái tên ngươi vừa khai báo lúc nãy cả. Kẻ này thật sự là "Chủ nhân" của ngươi sao?',
    'STm10001_01.166': 'Hả? Họ đang nói chuyện gì thế? Chủ nhân á?',
    'STm10001_01.170': 'Hừ. Một Dạ Hành Giả nơi thôn dã thì biết cái gì chứ? Đây hoàn toàn là tác dụng phụ bình thường của việc luyện tập ma pháp thôi mà.',
    'STm10001_01.177': 'Chủ nhân, người lại nhận nhầm em với Iris nữa rồi! Là em đây, Elis. Chị gái của Iris. Kẻ nô lệ trung thành và khiêm nhường của người đây mà.',
    'STm10001_01.193': 'Đúng vậy, Elis! Đó chính là cái tên đáng yêu mà người đã ban tặng cho em đấy.',
    'STm10001_01.197': 'Kẻ Nô Lệ Trung Thành (?)',
    'STm10001_01.200': 'Đầu óc người hẳn là đang quay cuồng lắm nhỉ. Nhưng đừng lo. Điều đó chỉ càng chứng minh rằng thuật hồi sinh của người đã thành công mỹ mãn thôi.',
    'STm10001_01.203': '<size=50><r=·>Đừng</r><r=·> cố</r><r=·> nói</r><r=·> gì</r></size>. Cứ nghỉ ngơi đi. Người sẽ sớm bình phục thôi.',
    'STm10001_01.212': 'Chuyện gì đang xảy ra thế này? Cô ấy trông giống hệt Iris, nhưng lại tự nhận mình là chị gái... Elis sao?',
    'STm10001_01.214': 'Còn giọng điệu của Noya thì sai quá sai. Kẻ tội đồ ư?==W== Khoan đã. Đây đâu phải Ốc Đảo May Mắn... Chẳng lẽ đây là xe áp giải tù nhân sao?',
    'STm10001_01.224': 'Trật tự mau! Kẻ tội đồ giảo hoạt kia.',
    'STm10001_01.228': 'Ngươi đang cuống cuồng tìm cách bịt miệng ==SEX4== đấy à. Bị nói trúng tim đen rồi sao?',
    'STm10001_01.230': 'Để ta đoán xem. Ngươi thậm chí còn chẳng quen biết kẻ này. Và ==SEX== chắc chắn chẳng phải "Chủ nhân" gì của ngươi hết.',
    'STm10001_01.235': 'Haizz, nói chuyện với kẻ đầu óc đơn giản như cô mệt mỏi thật đấy. Được thôi. Rửa sạch tai mà nghe cho rõ đây.',
    'STm10001_01.237': 'Chủ nhân của tôi là người phụng sự Nữ Thần Trivia, được Bán Thần Lucilla ưu ái che chở, và là Tu Giả Tập Sự đầy triển vọng nhất ở Emor đấy.',
    'STm10001_01.238': 'Ở Emor, bất kỳ ai muốn trở thành một Tư Tế chính thức đều phải dâng lên một ma pháp độc nhất vô nhị tại thần điện của Nữ Thần Trivia.',
    'STm10001_01.243': 'Thế nhưng sáng tạo ma pháp là một việc vô cùng nguy hiểm. Những phép thuật chưa hoàn thiện rất dễ ăn mòn tâm trí và làm xáo trộn ký ức của người thi triển.',
    'STm10001_01.244': 'Để bảo đảm an toàn cho mọi người, người chủ nhân nhân từ của tôi đã tự giam mình ==SEX8== trong một tòa tháp nơi Hoang Dã để dấn thân vào điều bất khả thi:',
    'STm10001_01.249': '<color=#3faeae><size=45>Thuật hồi sinh.',
    'STm10001_01.254': '<size=50><color=#3faeae>Thuật ... hồi sinh ư...</color></size>==W== Nói dối. Làm gì có thứ ma pháp nào như thế trên đời.',
    'STm10001_01.257': 'Chính xác! Thế nên người mới phải mày mò sáng tạo từ con số không đấy! Và nhờ vào thiên tài kiệt xuất của Chủ nhân, ==SEX== đã hoàn thiện được nó rồi!',
    'STm10001_01.258': 'Mấy ngày qua chính mắt cô cũng thấy rồi còn gì.',
    'STm10001_01.260': 'Chủ nhân của tôi từng không có nhịp tim, không có hơi thở, thân nhiệt cũng lạnh ngắt. Thế mà giờ hãy nhìn ==SEX4== xem. Vẫn hoàn toàn sống sờ sờ ra đấy thôi!',
    'STm10001_01.261': 'Chẳng phải điều đó đã chứng minh ma pháp đã thành công mỹ mãn rồi sao?',
    'STm10001_01.262': 'Ta không tin. Rõ ràng là ngươi đã dùng một ma pháp nào đó để đưa ==SEX4== vào trạng thái chết giả.',
    'STm10001_01.267': 'Tránh ra. Ta có vài câu muốn hỏi "Chủ nhân" của ngươi.',
    'STm10001_01.270': 'Biết thân biết phận chút đi, Dạ Hành Giả! Cô không có thẩm quyền thẩm vấn một Tu Giả Tập Sự cao quý đâu.',
    'STm10001_01.273': 'Nói vậy là nữ hiệp sĩ trông giống Noya đang truy lùng Iris...',
    'STm10001_01.275': 'Không. Cô ấy đang truy lùng Elis, người chỉ tình cờ có ngoại hình giống hệt Iris.==RT==Còn mình thì chẳng hiểu sao lại bị vạ lây, rốt cuộc thành ra bị nhốt chung chuồng thế này.',
    'STm10001_01.276': 'Như vậy chỉ có hai khả năng.',
    'STm10001_01.281': 'Một là: Elis đang nói dối không chớp mắt. Toàn bộ tràng độc thoại dài ngoằng vừa rồi chỉ là mớm lời cho mình diễn kịch.',
    'STm10001_01.283': 'Cô nàng muốn mình phối hợp vào vai Tu Giả Tập Sự cao quý để cậy quyền thế mà thoát khỏi người canh giữ.',
    'STm10001_01.290': 'Hai là: Elis nói thật. Cô ấy thực sự có một người em gái tên là Iris, và cô ấy cũng quen một Tu Giả Tập Sự nghiên cứu thuật hồi sinh có diện mạo giống hệt mình.',
    'STm10001_01.293': 'Làm gì có chuyện trùng hợp hoang đường đến mức ấy trên đời chứ!',
    'STm10001_01.296': 'Mà nghĩ lại thì... Rốt cuộc đây là đâu vậy? Nữ Thần Trivia? Bán Thần Lucilla? Emor là cái tên duy nhất mình nhận ra.',
    'STm10001_01.297': 'Liệu điều đó có nghĩa là mình vẫn đang ở Nova không?==W== Không. Ở Nova đã từ lâu lắm rồi làm gì còn chế độ nô lệ nữa.',
    'STm10001_01.304': 'Chẳng lẽ việc bước qua cánh cửa trong Phòng Trắng đã đẩy mình sang một thế giới song song sao?',
    'STm10001_01.305': 'Hay là... mình vẫn đang mơ? Hoặc không lẽ... tất cả chỉ là ảo giác vào khoảnh khắc mình bị chém đầu?',
    'STm10001_01.308': 'Em nghĩ sao hả, Vita?',
    'STm10001_01.316': '... Phải rồi. Mình đang làm cái gì thế này? Vita đã vỡ vụn khi cố cứu mạng mình rồi mà.',
    'STm10001_01.318': 'Haizz, thôi không suy nghĩ luẩn quẩn nữa. Bất kể đây là đâu, ưu tiên số một lúc này là phải thoát khỏi cái lồng này đã. Đến lúc phải nói chuyện với cô nàng Dạ Hành Giả kia rồi.',
    'STm10001_01.320': 'Elis, bảo Dạ Hành Giả qua đây một lát.',
    'STm10001_01.322': 'Chủ nhân? Người đâu cần phải bận tâm đến yêu cầu của một Dạ Hành Giả thấp kém chứ.',
    'STm10001_01.326': 'Cô ta nhốt chúng ta vào cái chuồng này mà chẳng có lấy nửa mảnh bằng chứng! Đúng là đồ mọi rợ mà.',
    'STm10001_01.327': 'Đợi đến khi vào thành, em nhất định sẽ tìm người bảo hộ của cô ta để bắt cô ta phải chịu phạt thích đáng.',
    'STm10001_01.331': 'Kính thưa ==SEX12== Tu Giả Tập Sự.==W== Tôi là Alina Colossi, Dạ Hành Giả của Filanis. Tôi phục vụ dưới trướng Chấp Chính Quan Olympia.',
    'STm10001_01.335': 'Alina Colossi',
    'STm10001_01.336': 'Dạ Hành Giả Filanis',
    'STm10001_01.337': 'Vì sự an toàn của ngài, tôi buộc phải hỏi ngài vài câu. Nếu kết quả chứng minh tôi đã phán đoán sai thân phận của hai người, tôi sẽ tạ lỗi và xin nhận mọi hình phạt từ ngài Olympia.',
    'STm10001_01.339': 'Cứ hỏi đi. Tôi vừa mới tỉnh dậy, đầu óc vẫn còn hơi choáng váng, nhưng trong khả năng thì tôi sẽ trả lời.',
    'STm10001_01.342': 'Rõ ràng chỉ là một sự hiểu lầm mới khiến chúng tôi bị nhốt vào đây. Hy vọng bây giờ chúng ta có thể làm sáng tỏ mọi chuyện.',
    'STm10001_01.343': 'Xin hãy cho tôi biết. Ngài có biết gì về Sự Kiện Thánh Nữ Mất Tích vào ba năm trước không?',
    'STm10001_01.344': 'Elis đưa mắt ra hiệu đầy ẩn ý cho tôi. Có vẻ cô ấy muốn tôi trả lời là có.',
    'STm10001_01.345': 'Vị Dạ Hành Giả này rõ ràng rất kính trọng thân phận Tu Giả. Nếu muốn ra khỏi đây, mình phải nhập tâm hết mức vào vai diễn Tu Giả Tập Sự này mới được.',
    'STm10001_01.348': '... Xem ra trước mắt đành phải phối hợp cùng Elis vậy.',
    'STm10001_01.350': 'Mình phải trả lời mập mờ nước đôi thôi. Tuyệt đối không được để cô ấy bắt bẻ sơ hở.',
    'STm10001_01.351': 'Ba năm trước... Tôi cũng có nghe loáng thoáng. Nhưng chuyện đó thì liên quan gì đến việc nhốt chúng tôi vào chuồng thế này?',
    'STm10001_01.353': 'Xin ngài hãy nhìn bức chân dung này.',
    'STm10001_01.354': '... Đây là!',
    'STm10001_01.355': 'Nếu được, tôi muốn nói riêng với ngài vài lời.',
    'STm10001_01.364': 'Alina dẫn tôi ra khỏi xe tù, đi tới dưới một gốc cây cách đó vài mét... Khoảng cách vừa đủ để Elis không nghe lén được.',
    'STm10001_01.369': 'Nô lệ của ngài trông rất giống Thánh Nữ mất tích năm xưa.==W== Cho phép tôi mạo muội hỏi, cô ấy trở thành nô lệ của ngài từ khi nào và ở đâu?',
    'STm10001_01.371': 'Thì ra Elis có thể chính là Thánh Nữ mất tích đó. Hèn chi lại bị truy bắt gắt gao như vậy.',
    'STm10001_01.372': 'Nhưng mình đã lỡ đâm lao thì phải theo lao với vai Tu Giả này rồi. Lúc này mình và Elis đang chung một thuyền. Đành phải diễn tiếp vậy.',
    'STm10001_01.374': 'Tôi và Elis gặp nhau ở Emor bốn năm trước rồi. Mốc thời gian hoàn toàn không khớp với vị Thánh Nữ mất tích của cô đâu. Cô ấy chỉ tình cờ trông giống bức chân dung thôi.',
    'STm10001_01.375': 'Tôi hiểu rồi. Ra là vậy.==W== Có vẻ như tôi đã nhầm lẫn. Thành thật xin lỗi ngài vì đã nhận nhầm nô lệ của ngài thành vị Thánh Nữ kia.',
    'STm10001_01.377': 'Sau khi đến Filanis, tôi sẽ bẩm báo chuyện này với người bảo hộ của tôi. Ngài sẽ được bồi thường thỏa đáng, còn tôi xin chịu mọi hình phạt.',
    'STm10001_01.378': 'Không cần phạt gì đâu. Dù sao thì gần đây tôi cũng chìm vào giấc ngủ sâu như chết vì nghiên cứu ma pháp mà.',
    'STm10001_01.379': 'Hiểu nhầm cũng là chuyện khó tránh. Chỉ cần đừng coi chúng tôi là nghi phạm nữa là được.',
    'STm10001_01.385': 'Ngài quả là vừa khiêm nhường lại vừa nhân từ, thưa ==SEX12== Tu Giả. Đa tạ lòng khoan dung của ngài. Tôi sẽ thả nô lệ của ngài ra khỏi xe ngay lập tức.',
    'STm10001_01.386': 'Nhân tiện, tôi lớn lên ở Emor. Tôi thực sự rất nhớ Đấu Trường Lớn ở đó. Vào những ngày thi đấu, khán giả đông nghìn nghịt, vé gần như không thể nào mua nổi. Ngài đã từng đi xem trận nào chưa?',
    'STm10001_01.387': 'Emor có đấu trường sao...? Lần đầu tiên mình nghe thấy đấy.==W== Nghe có vẻ các trận đấu ở đó náo nhiệt lắm. Nếu mình bảo có, cô ấy sẽ hỏi vặn vẹo chi tiết ngay.==W== Mình cần một lý do hợp lý để thoái thác mới được.',
    'STm10001_01.391': 'Khụ. Tiếc là chưa.',
    'STm10001_01.392': 'Là một Tu Giả Tập Sự, việc học tập nghiên cứu khiến tôi chẳng có mấy thời gian rảnh rỗi. Vả lại... vé cũng khó mua vô cùng, đúng như lời cô vừa nói đấy.',
    'STm10001_01.403': 'Chủ nhân. Người đã quay lại rồi.',
    'STm10001_01.410': 'Ừ. Hiểu lầm đã được giải tỏa rồi. Cô ấy sẽ thả em ra.',
    'STm10001_01.415': 'Thưa ==SEX12== Tu Giả, có một chuyện ngài cần phải biết. Những lời đồn đại về vị Thánh Nữ mất tích không hoàn toàn chính xác đâu.',
    'STm10001_01.419': 'Thiên hạ đều tin rằng ba năm trước, một vị Thánh Nữ đã biến mất đầy bí ẩn trong nghi lễ tại tòa tháp ở Emor. Người ta đồn rằng cô ấy bị một ma pháp sư hùng mạnh bắt cóc.',
    'STm10001_01.421': 'Thế nhưng với tư cách là một Dạ Hành Giả của Filanis,==W== tôi đã được nghe sự thật đằng sau chuyện đó.',
    'STm10001_01.426': 'Chẳng có vụ bắt cóc nào cả. Tất cả đều do chính vị Thánh Nữ Sa Ngã đó tự biên tự diễn.==RT==Ả đã phản bội lại vị thần mà mình phụng sự rồi trốn chạy khỏi buổi tế lễ.',
    'STm10001_01.428': 'Để che giấu tung tích, suốt ba năm qua ả đã lang bạt qua các thành phố,==RT==ra tay diệt khẩu bất kỳ ai phát hiện ra mình. Đã có tới mười lăm người thiệt mạng dưới tay ả.',
    'STm10001_01.430': 'Sở trường của ả là mê hoặc những kẻ vô tội để biến họ thành bia đỡ đạn. Các nạn nhân trong cơn u mê sẽ ra sức bảo vệ và nói dối nhằm che đậy dấu vết cho ả.',
    'STm10001_01.431': 'Elis là Thánh Nữ Sa Ngã ư? Còn mình thì đang bị cô ấy mê hoặc?==W== Không. Mình có kháng tính với ma pháp, sao có thể bị mê hoặc được chứ.',
    'STm10001_01.434': 'Khí chất tao nhã và y phục thượng lưu của ngài cho thấy ngài đúng là một Tu Giả Tập Sự, hoặc chí ít cũng là người có địa vị tương đương.',
    'STm10001_01.438': 'Ánh mắt của ngài rất trong trẻo, không hề có dấu hiệu bị trúng ma pháp mê hoặc. Điều đó dẫn đến một câu hỏi: tại sao ngài lại bao che cho một kẻ tội đồ và cam tâm tình nguyện nói dối vì ả?',
    'STm10001_01.440': 'Khi nhắc đến Elis, ngài chưa từng một lần gọi cô ta là nô lệ. Ngài không xem cô ta là tài sản. Một người chủ thực sự sẽ không bao giờ đối xử với ==SEX8== theo cách như vậy.',
    'STm10001_01.445': 'Theo tôi thấy, giữa hai người căn bản chẳng hề có quan hệ chủ tớ nào cả.',
    'STm10001_01.447': 'Dĩ nhiên, chỉ bấy nhiêu thì chưa đủ để kết tội ngài. Nhưng sơ hở tiếp theo của ngài đã chứng minh ngài tuyệt đối không phải là người từ Emor tới.',
    'STm10001_01.448': 'Đấu Trường Lớn không hề bán vé. Ở đó làm gì có vé. Khán giả vào xem đều sử dụng thẻ đất nung miễn phí.',
    'STm10001_01.449': 'Cái gì? Nhưng cô vừa bảo...',
    'STm10001_01.454': 'Thứ lỗi cho chút mánh khóe lừa gạt của tôi.',
    'STm10001_01.458': 'Người phụ nữ trước mặt ngài vô cùng nguy hiểm. Ả tự nhận mình là nô lệ của ngài chắc chắn có uẩn khúc.',
    'STm10001_01.461': 'C-Chủ nhân... Đừng nghe lời cô ta, em là người trung thành nhất của...',
    'STm10001_01.464': 'Kẻ tội đồ kia! Đứng im, không được manh động. Bỏ tay ra khỏi viên đá trước ngực ngay.',
    'STm10001_01.467': 'Hừm. Ai ngờ nơi hẻo lánh như Filanis lại đào tạo ra được một Dạ Hành Giả sắc sảo đến vậy chứ.',
    'STm10001_01.475': 'Hỡi Thần Ma Pháp,==W== xin hãy giăng màn sương u minh phủ kín mặt đất.==W== Che mờ mắt kẻ thù,==W== để ta bước đi không một dấu vết.',
    'STm10001_01.485': 'Ma pháp tàng hình ư?',
    'STm10001_01.487': 'Tia lửa bùng cháy thành hỏa diễm.==W== Hãy vạch trần kẻ ẩn mình!',
    'STm10001_01.496': 'Hì hì. Đâu phải cứ câu thần chú nói là ẩn mình thì sẽ biến thành tàng hình đâu chứ.',
    'STm10001_01.501': 'Ma pháp gia tốc sao?!',
    'STm10001_01.508': 'Cảm ơn vì đã phối hợp nhé, "Tu Giả Tập Sự". Nếu anh không dụ cô ta đi xa mười bước, tôi đã chẳng bao giờ có đủ thời gian để chuẩn bị ma pháp trận rồi.',
    'STm10001_01.509': 'Vậy thì hẹn gặp lại lần sau nhé. Dạ Hành Giả sắc sảo và Tu Giả nhân từ.',
    'STm10001_01.518': '... Cô ấy vừa kích hoạt những con rối bỏ hoang trong rừng đấy ư?',
    'STm10001_01.526': 'Thưa Tu Giả. Mau đóng cửa xe lại và ngồi yên bên trong. Đó là nơi an toàn nhất cho ngài lúc này.',
    'STm10001_01.532': 'Tôi sẽ dọn sạch lũ rối này!',
    'STm10001_02.4': 'Hồi 2',
    'STm10001_02.5': 'Thành Phố Hoàn Hảo',
    'STm10001_02.6': 'Elis cứu bạn khỏi lũ rối, xua tan phần nào mối nghi ngờ của Alina. Những ngày tiếp theo trên đường đi, bạn và Elis dần trở nên thân thiết hơn qua những dòng chữ viết vụng trộm trong lòng bàn tay. Khi đặt chân đến Filanis, bạn bỗng cảm nhận được một thoáng quen thuộc mơ hồ…',
    'STm10001_02.60': 'Con Rối Vô Hồn',
    'STm10001_02.62': 'Kẽo kẹt, kẽo kẹt.',
    'STm10001_02.68': 'Lũ rối này dai như đỉa đói vậy. Alina rõ ràng đã chém chúng ra thành trăm mảnh vụn trước khi đuổi theo rồi, thế mà...',
    'STm10001_02.91': 'Bây giờ chúng lại tự bẻ tay bẻ chân của chính mình rồi chắp vá lại thành năm thân xác mới.',
    'STm10001_02.100': 'Cũng may là các chấn song này đủ kiên cố. Lũ này có đập phá điên cuồng đến đâu cũng chẳng để lại nổi một vết xước.',
    'STm10001_02.103': 'Cứ theo đà này... mình sẽ hoàn toàn an toàn trong này cho đến khi... chết đói.',
    'STm10001_02.105': 'Nhưng nếu chẳng có ai tới cứu, mình sẽ chết đói ở đây thật mất.',
    'STm10001_02.108': 'Được rồi, hoảng loạn lúc này chẳng giải quyết được gì. Phải nhớ lại mọi chuyện từ đầu xem nào.',
    'STm10001_02.114': 'Mình nhớ là...==W== mình đã cố sử dụng năng lực "đi lại nước cờ" để đánh bại Angie. Để tìm ra một lối thoát mà không ai phải bỏ mạng.',
    'STm10001_02.122': 'Nhưng điều đó đồng nghĩa với việc vứt bỏ tính mạng của chính mình. Nếu không có Vita dùng Ngai Vàng đỡ đòn hiểm đó, chắc mình đã mất mạng từ lâu rồi.',
    'STm10001_02.127': 'Ngai Vàng đã vỡ vụn. Khi tỉnh lại, mình thấy mình bị nhốt trong Phòng Trắng, không một bóng dáng nhân viên Cự Tháp nào quanh đây. Nơi đó chỉ là một khoảng hư vô bất tận.',
    'STm10001_02.128': 'Mình cứ bước đi mãi... bước đi cho đến khi tâm trí dần tê liệt. Rồi mình nghe thấy một giọng nói quen thuộc, và đẩy mở cánh cửa tiếp theo.',
    'STm10001_02.137': 'Để rồi bị tống thẳng tới chốn này.==W== Cảm giác chẳng khác nào khoảnh khắc tỉnh giấc trên Ốc Đảo May Mắn năm xưa, chỉ có điều...',
    'STm10001_02.141': 'Noya lại là một Dạ Hành Giả,==W== Iris thì hóa thành Thánh Nữ Sa Ngã,==W== còn Amber... thì chẳng thấy tăm hơi đâu cả.',
    'STm10001_02.148': '... Đây là một giấc mơ sao? Không, làm sao người ta có thể mơ thấy những điều mình chưa từng biết chứ.',
    'STm10001_02.149': 'Một ảo ảnh bên trong Phòng Trắng ư? Hay là một thế giới hoàn toàn khác? Mình thực sự chịu chết.',
    'STm10001_02.150': 'Nhưng điều đó không quan trọng. Mình đã tìm thấy lối thoát trong Phòng Trắng, nghĩa là mình vẫn chưa thua cuộc.',
    'STm10001_02.152': 'Dù bị chặt đầu chẳng phải trải nghiệm dễ chịu gì, nhưng mình vẫn lách qua được cánh cửa định mệnh đó thôi.',
    'STm10001_02.155': 'Dù có là ngõ cụt đi chăng nữa, ắt hẳn vẫn sẽ có lối ra. Vì mọi người, và vì cả Vita nữa... mình nhất định phải trở về!',
    'STm10001_02.162': 'Chuyện gì đang xảy ra thế? Sao cỗ xe lại rung lắc dữ dội thế này?',
    'STm10001_02.168': 'Lạch cạch, lạch cạch.',
    'STm10001_02.170': 'Khoan đã, sao tất cả bọn chúng lại dồn hết sang một bên xe thế kia?!',
    'STm10001_02.179': 'Răng rắc, lạch cạch.',
    'STm10001_02.182': 'Bọn chúng đang muốn lật nhào cỗ xe! Nếu xe đổ, chúng có thể thò tay qua song sắt tóm lấy mình!',
    'STm10001_02.186': 'Alina! Mau quay lại đây! Cái chuồng sắp sập rồi!',
    'STm10001_02.193': 'Hỡi Thần Ma Pháp, xin ban cho con ngọn thánh hỏa rực cháy...',
    'STm10001_02.196': 'Bóng hình kia...==W== Elis sao?',
    'STm10001_02.202': '... Hãy thiêu rụi khu rừng tà ác này!',
    'STm10001_02.204': 'H-Hỏa thuật ư?! Này, đừng nướng sống tôi chứ!',
    'STm10001_02.211': 'Ồ... Là phong nhận...',
    'STm10001_02.214': 'Thấy chưa hả Chủ nhân kính yêu của em? Rốt cuộc người vẫn luôn cần đến em mà thôi. Cô nàng Dạ Hành Giả kia vô tích sự thật đấy.',
    'STm10001_02.216': 'Cô ta chỉ thấy song sắt cứng cáp rồi đinh ninh bạo lực không phá nổi. Nhưng cô ta quên mất lũ này cũng có chút mưu mẹo. Tường đồng vách sắt có nghĩa lý gì nếu kẻ địch cứ việc trèo qua chứ.',
    'STm10001_02.217': 'Sao cô lại ở đây? Alina ở ngay gần đây thôi. Nếu cô ấy thấy cô, cô ấy sẽ bắt cô đấy. Mau đi đi.',
    'STm10001_02.220': 'Ồ? Chủ nhân thực sự đang lo lắng cho em sao. Em thấy vinh hạnh ghê đó nha.',
    'STm10001_02.224': 'Em là một Thánh Nữ Sa Ngã giết người không ghê tay cơ mà, người quên rồi à?',
    'STm10001_02.226': 'Người đã nhìn thấy mặt em, nghe thấy giọng em. Người không sợ em sẽ diệt khẩu nhân chứng duy nhất này sao?',
    'STm10001_02.228': 'Nếu cô đến để giết người diệt khẩu, cô đã chẳng cứu tôi làm gì. Cứ để mặc lũ rối ra tay chẳng phải tiện hơn nhiều sao.',
    'STm10001_02.229': 'Hơn nữa... Cô có thể là Thánh Nữ Sa Ngã thật, nhưng tôi không nghĩ cô sẽ giết người chỉ để xóa dấu vết đâu.',
    'STm10001_02.230': 'Thú vị thật đấy. Người mới tỉnh lại nửa tiếng trước, chúng ta cũng chỉ vừa mới gặp nhau. Lòng tin này từ đâu mà ra vậy?',
    'STm10001_02.233': 'Đừng nói là... người mê đắm nhan sắc của em rồi đấy nhé, hay là người thích nghe em ngọt ngào gọi hai tiếng Chủ nhân?',
    'STm10001_02.235': 'Bởi vì==W== tôi không đời nào tin một người có gương mặt giống hệt Iris lại là kẻ sát nhân...==W== Haizz. Nhưng nói thẳng câu đó ra mồm thì ai mà tin cho nổi.',
    'STm10001_02.240': 'Khụ. Không phải vì nhan sắc. Mà là vì cách hành sự của cô.',
    'STm10001_02.241': 'Không phải vì nhan sắc sao? Em hiểu rồi. Người bị em hớp hồn rồi chứ gì. Chỉ là người có lý do khác để tin tưởng em thôi.',
    'STm10001_02.242': 'Giờ thì em tò mò rồi đấy. Rốt cuộc hành động nào của em đã làm lộ tẩy thế?',
    'STm10001_02.243': 'Chà... Cái tính cách nghịch ngợm láu lỉnh này chẳng giống Iris chút nào. Tốt nhất là mình cứ nói toẹt ra cho cô ấy hiểu.',
    'STm10001_02.244': 'Cô là một ma pháp sư hùng mạnh. Nếu cô là kẻ giết người tàn nhẫn, cô việc gì phải lôi một kẻ mất trí nhớ ngơ ngác vào vở kịch giả mạo thân phận này.',
    'STm10001_02.246': 'Alina là một người lão luyện. Cô ấy vạch trần câu trả lời của tôi chỉ trong vài giây. Đối đầu với một đối thủ như thế, đánh lén bằng ma pháp mới là lựa chọn tối ưu nhất của cô.',
    'STm10001_02.247': 'Khi chúng ta bước ra ngoài xe, cô đúng là đã bí mật bố trí ma pháp trận. Thế nhưng đó chỉ là ma pháp gia tốc, hoàn toàn không gây sát thương.',
    'STm10001_02.249': 'Thói quen thì khó bỏ lắm. Cô luôn tránh làm người khác bị thương, và rõ ràng cô đã cố hết sức để tôi không bị cuốn vào vòng nguy hiểm. Cô căn bản không phải kẻ thủ ác máu lạnh.',
    'STm10001_02.252': 'Chậc. Đúng là một ngày kỳ lạ. Đầu tiên là một Dạ Hành Giả sắc sảo, giờ lại đến một Chủ nhân ra sức uốn lưỡi để chứng minh em vô tội.',
    'STm10001_02.255': 'Thôi chuyện của em nói thế đủ rồi. Chúng ta phải chuồn mau thôi.',
    'STm10001_02.264': 'Cô định cướp luôn cả cỗ xe này sao?!',
    'STm10001_02.266': 'Chính xác. Để xem cô nàng Dạ Hành Giả kia đuổi theo kiểu gì. Cứ để cô ta ở lại khu rừng này mà chơi đùa với đống sắt vụn cả đêm đi.',
    'STm10001_02.268': 'Ồ hố, lại có chướng ngại vật cản đường này.',
    'STm10001_02.271': 'Hỡi Thần Ma Pháp, xin ban cho con ngọn thánh hỏa rực cháy... Hãy thiêu rụi khu rừng tà ác này!',
    'STm10001_02.272': 'Đúng ma pháp rồi, nhưng đọc sai thần chú. Thói quen thi triển của cô nàng này kỳ quặc thật...',
    'STm10001_02.278': 'Khoan đã, mặt của lũ rối vừa đổi màu đấy ư?',
    'STm10001_02.283': 'Phong nhận... biến mất rồi sao?! Trên người chúng có kết giới kháng gió ư?!',
    'STm10001_02.285': 'Thế thì đỡ chiêu này xem!',
    'STm10001_02.286': 'Hỡi Thần Ma Pháp, xin hãy để đôi cánh nhanh nhẹn nhất của rừng sâu nghe theo mệnh lệnh của con. Hãy thanh tẩy thế giới ồn ã này!',
    'STm10001_02.296': 'S-Sao có thể như thế được? Chẳng ai lại lãng phí hai loại kết giới khác nhau lên đống phế liệu cả!==W== Khoan đã... Không chỉ là kết giới. Chúng đang nuốt chửng ma lực của mình!',
    'STm10001_02.299': 'Elis, cẩn thận!',
    'STm10001_02.304': 'Ư... Ma pháp của em vô dụng rồi. Chúng ta bị bao vây rồi.',
    'STm10001_02.305': 'Vào trong này mau! Cái lồng sắt sẽ chặn được chúng!',
    'STm10001_02.306': 'Không được. Nếu em mở cửa bây giờ, chúng sẽ ùa vào trong mất,==W== lúc đó cả hai chúng ta đều sẽ chết...',
    'STm10001_02.308': 'Lấy nền tảng linh hồn ta làm móng, lấy thần phách ta làm vữa... Ta phong ấn chiếc lồng của Chủ nhân. Hãy chống chọi bão giông, đứng vững trước cuồng phong, kiên cường qua lửa bỏng...',
    'STm10001_02.311': 'Elis, cô đang làm cái trò gì thế?!',
    'STm10001_02.313': 'Khó khăn lắm em mới gặp được một người hiểu mình. Em sẽ không để anh phải chết ngày hôm nay đâu, Tu Giả. Đây là tất cả chút ma lực còn sót lại của em. Nhận lấy đi.',
    'STm10001_02.316': 'Kết giới này chắc sẽ trụ được... Ít nhất là cho đến khi Dạ Hành Giả quay lại...==W==',
    'STm10001_02.331': 'Diễm Hỏa Rực Rỡ!',
    'STm10001_02.347': 'Bọn chúng đột nhiên trở nên kiên cố hơn. Mình không nhận ra loại ma pháp bảo hộ này...',
    'STm10001_02.348': 'Alina, thu hồi ma pháp lại mau! Chúng đang hấp thụ ma lực từ thanh kiếm của cô đấy!',
    'STm10001_02.349': 'A, tôi hiểu rồi.==W== Vậy thì tôi sẽ chém nát chúng bằng kiếm thuật thuần túy!',
    'STm10001_02.357': 'Đúng như tôi nghĩ. Cách này dễ dàng hơn nhiều.',
    'STm10001_02.359': 'Tránh xa cỗ xe ra mau!',
    'STm10001_02.366': 'Đây là nhát kiếm kết liễu!',
    'STm10001_02.373': 'Thật không thể tin nổi... Cô ấy chém gục năm mươi,==W== không, ít nhất cũng phải một trăm con rối chỉ bằng kiếm thuật đơn thuần thôi sao?!',
    'STm10001_02.374': 'Thưa ==SEX12== Tu Giả, ngài có sao không? Có bị thương ở đâu không?',
    'STm10001_02.375': 'Tôi ở trong xe an toàn rồi. Mau đi tìm Elis đi! Lũ rối vừa vùi lấp cô ấy rồi!',
    'STm10001_02.380': 'C-Chủ nhân, em không sao.',
    'STm10001_02.381': 'Đừng lo. <color=#3faeae>Nô lệ</color> của ngài cũng biết thân biết phận, đã nhanh trí chui xuống dưới đống đổ nát ẩn nấp khi tôi vung kiếm rồi.',
    'STm10001_02.384': 'Cô cũng khéo nói ghê nhỉ! Nhát chém cuối cùng suýt nữa thì phạt bay đầu tôi đấy!',
    'STm10001_02.385': 'Khoan đã. Cô vừa gọi tôi là gì cơ?',
    'STm10001_02.386': 'Tôi đã kiểm tra lũ rối trong rừng rồi. Không phải ma pháp của cô kích hoạt chúng.==W== Hơn nữa, tôi cũng đã thấy những gì cô làm...',
    'STm10001_02.387': 'Ngay trong khoảnh khắc cận kề cái chết, cô đã dốc cạn chút ma lực cuối cùng để tạo kết giới bảo vệ cho Tu Giả. Một Thánh Nữ Sa Ngã sẽ không bao giờ làm điều đó. Chỉ có một nô lệ tuyệt đối trung thành mới hành động như vậy.',
    'STm10001_02.388': 'Cô vẫn có thể là Thánh Nữ Sa Ngã ẩn mình sau lớp ngụy trang tinh vi, nhưng chân tướng đó giờ đã vượt quá quyền phán xét phàm trần của tôi rồi.',
    'STm10001_02.389': 'Tôi sẽ đưa cả hai người tới Filanis. Người bảo hộ của tôi,==W== Chấp Chính Quan <color=#3faeae>Olympia</color> vĩ đại, sẽ phán xét thân phận và định đoạt số phận của hai người.',
    'STm10001_02.391': 'Ba ngày sau.',
    'STm10001_02.396': '==A-2==Sau khi Alina đột ngột dừng cuộc thẩm vấn, chúng tôi tiếp tục lên đường.==P====RT====RT====A-1==Trên danh nghĩa, Elis vẫn là một kẻ tội đồ còn tôi là tẩu phạm tình nghi. Thế nhưng Alina lại đối đãi với chúng tôi hệt như một Tu Giả Tập Sự cùng thị giả của ==SEX3==, dành trọn cho chúng tôi mọi sự kính trọng tương xứng với thân phận ấy.==P====RT====RT====A-1==Thậm chí ba bữa ăn mỗi ngày của chúng tôi còn ngon lành hơn lương khô của cô ấy gấp bội phần.',
    'STm10001_02.397': 'Ngồi xóc nảy trên cỗ xe, tôi và Elis ngày càng trở nên thân thiết hơn,==RT==hình thành nên một phương thức trò chuyện vô cùng độc đáo.',
    'STm10001_02.400': '(Viết lại theo ngón tay em một lần nữa đi, ==PLAYER_NAME==! Một Tu Giả Tập Sự mà đến cả tên của ==SEX3== cũng không biết viết thì đúng là sơ hở chí mạng đấy.)',
    'STm10001_02.401': '(Hiểu rồi. Thử lại lần nữa nhé. Thế này đúng chưa?)',
    'STm10001_02.402': '(Tạm được thôi. Nét chữ của anh đúng là thảm họa.)',
    'STm10001_02.403': '(Từ giờ trở đi mọi việc ghi chép cứ để em lo hết. Dù sao thì việc đó cũng hoàn toàn khớp với thân phận nô lệ hầu cận.)',
    'STm10001_02.405': '(Hôm trước sao tự nhiên Alina lại bỏ ngang cuộc thẩm vấn thế? Cô có nghĩ ra lý do gì không?)',
    'STm10001_02.406': '(Em đoán được vài phần. Cô ta rất sắc sảo. Hẳn cô ta cũng nhận ra điểm mâu thuẫn giống như anh thôi. Cách hành xử của em chẳng giống chút nào với vị Thánh Nữ Sa Ngã mà cô ta được nghe kể.)',
    'STm10001_02.407': '(Hơn nữa, phong thái của anh trông cũng rất ra dáng quý tộc. Bắt giữ nhầm nô lệ riêng của anh sẽ khiến cô ta bị người bảo hộ khiển trách nặng nề đấy.)',
    'STm10001_02.408': '(Nhưng cô thực sự là vị Thánh Nữ bỏ trốn đó phải không?)',
    'STm10001_02.411': '(Giấu anh cũng chẳng để làm gì. Đúng là em đã bỏ trốn khỏi buổi tế lễ, nhưng suốt ba năm qua em chỉ ru rú trong tòa tháp gần Emor để nghiên cứu ma pháp thôi.)',
    'STm10001_02.412': '(Em hoàn toàn mù tịt về những tội ác kia. Đợi khi chúng ta ra khỏi đây, em sẽ cho anh xem nhật ký hàng ngày của em trong tòa tháp. Chúng sẽ chứng minh em trong sạch!)',
    'STm10001_02.414': '(Mấy ngày trước em đang ngủ say như chết trong tháp.)',
    'STm10001_02.416': '(Thế rồi cô nàng Dạ Hành Giả kia đùng đùng xông vào cầm theo bức chân dung định bắt em.)',
    'STm10001_02.418': '(Em chạy thục mạng qua Cự Tháp.==RT==Ngay lúc sắp kiệt sức ngã quỵ, em nhìn thấy một cỗ quan tài chạm trổ tinh xảo.)',
    'STm10001_02.421': '(Em định chui vào trốn, ai ngờ anh đã nằm sẵn trong đó rồi.)',
    'STm10001_02.422': '(Trông anh ăn mặc quý phái như vương công quý tộc, nên em mới nhận bừa anh là Tu Giả Tập Sự==RT==đang trong trạng thái hồi sinh mê man, còn em là nô lệ canh gác cho anh.)',
    'STm10001_02.423': '(Tự nguyện nhận mình là nô lệ... Có cần thiết phải làm đến mức đó không?)',
    'STm10001_02.424': '(Anh chẳng nhớ gì thật đấy à. Nô lệ là tài sản riêng. Nếu cô ta muốn bắt em, cô ta buộc phải có sự cho phép của chủ nhân trước.)',
    'STm10001_02.425': '(Chỉ cần em nhận là người của anh, cô ta bắt buộc phải xác minh quyền sở hữu của anh trước khi lôi em đi, bất kể em có là Thánh Nữ Sa Ngã hay không.)',
    'STm10001_02.426': '(Thế nên cô ta mới vác cả anh lẫn cỗ quan tài lên xe để điều tra đấy. Cô ta còn dọa nếu thân phận không khớp, cô ta sẽ khép em vào tội xúc phạm thi thể nữa cơ.)',
    'STm10001_02.427': '(Nhờ có anh mà em câu kéo thêm được bao nhiêu thời gian. Nếu không thì giờ em đã bị xích tay còng chân, đừng hòng vẽ nổi lấy nửa cái ma pháp trận.)',
    'STm10001_02.428': '(Mà nhắc mới nhớ, rốt cuộc anh là ai vậy? Sao anh lại nằm trong cỗ quan tài trên đỉnh Cự Tháp thế? Suốt ba năm qua em chưa từng thấy ai mò lên đó bao giờ.)',
    'STm10001_02.429': 'Mình sao có thể giải thích nổi chuyện bước qua Phòng Trắng để tới thế giới này được chứ... Đành phải kể tóm tắt đại khái cho cô ấy nghe vậy.',
    'STm10001_02.431': '(Tôi không phải Tu Giả gì đâu, và tôi đến từ một nơi rất, rất xa. Còn lý do vì sao tôi lại nằm trong cỗ quan tài đó trên Cự Tháp thì nói thật tôi cũng chịu chết.)',
    'STm10001_02.432': '(Chẳng sao cả. Trông anh ra dáng lắm rồi. Sẽ chẳng ai nghi ngờ vỏ bọc Tu Giả này đâu. Đến <color=#3faeae>Filanis</color> cứ để em lo liệu ăn nói, kẻo chúng ta bị lộ tẩy.)',
    'STm10001_02.434': '(Em sẽ tiếp tục đóng vai nô lệ của anh.==W== Nhưng nghiêm túc đấy, anh phải tỏ ra nghiêm khắc hơn với em một chút. Phải ra dáng quyền uy lên! Chẳng có ai lại đối xử với nô lệ dịu dàng như anh đâu.)',
    'STm10001_02.435': '(Với cô nàng Dạ Hành Giả kia cũng thế. Bỏ cái vẻ lịch thiệp nhã nhặn ấy đi, diễn thế lộ liễu lắm. Nhưng nếu cô ta phục vụ chu đáo, hãy ban thưởng cho cô ta thật hậu hĩnh.)',
    'STm10001_02.436': '(Tôi hiểu rồi. Tôi sẽ cố.)',
    'STm10001_02.437': '(Mà này... Cái trò viết chữ trong lòng bàn tay này có qua mắt được Alina thật không đấy?)',
    'STm10001_02.440': '(Chắc chắn rồi. Cô ta đang mải điều khiển ngựa mà. Với lại lỡ cô ta có nghi ngờ mờ ám, em cũng có thừa cách để đánh lạc hướng cô ta.)',
    'STm10001_02.443': 'Kính thưa các vị tội đồ. Chúng ta đã tới nơi rồi.',
    'STm10001_02.445': 'Chết thật, mải tập trung quá nên mình chẳng nhận ra cỗ xe đã dừng lại từ lúc nào.==W== Bị bắt quả tang rồi!',
    'STm10001_02.447': 'Á... Chủ nhân.',
    'STm10001_02.450': 'Người xoa như thế, cảm giác...==W== kỳ lạ lắm. Ngón tay của người...==W== có thể nhẹ nhàng hơn một chút được không?',
    'STm10001_02.453': 'Ờ... Đ-Được rồi. Ta biết rồi...',
    'STm10001_02.455': 'Cái cớ chữa cháy điên rồ quái quỷ gì thế này trời?!',
    'STm10001_02.456': 'Khụ. Những hành vi thân mật lập dị giữa chủ nhân và nô lệ cũng là chuyện thường thấy,==W== nhưng hai người nấn ná như vậy là đủ lâu rồi đấy. Đến lúc phải xuống xe rồi.',
    'STm10001_02.457': 'Xuống xe ư? Ở đây sao?',
    'STm10001_02.462': 'Xét đến thân phận được cho là của ngài, việc áp giải ngài vào thành trên một cỗ xe tù khi sự thật chưa sáng tỏ sẽ là một điều sỉ nhục.',
    'STm10001_02.463': 'Khụ. Cô chu đáo đến bất ngờ đấy. Chủ nhân của tôi là một Tu Giả danh giá. ==SEX1== tuyệt đối không thể diện kiến Chấp Chính Quan cùng với ==SEX8== trong bộ dạng nhếch nhác lem luốc thế này được.',
    'STm10001_02.464': 'Đúng vậy. Xét theo tình cảnh của hai người, tôi đã đặc biệt chọn một nhà tắm công cộng đóng cửa nghỉ tiếp khách hôm nay. Ở đây chỉ có ba chúng ta thôi.',
    'STm10001_02.465': 'Chu đáo thật đấy. Cơ mà chỗ này trông chẳng giống nơi có nhà tắm gì cả. Filanis thực sự hẻo lánh đến mức này sao?',
    'STm10001_02.466': 'Đây chưa phải nội thành Filanis. Nơi này chỉ là một khu định cư tự phát được dựng lên ở ngoại ô thôi.',
    'STm10001_02.471': 'Hãy nhìn đằng kia xem. Thành phố đang tỏa sáng rực rỡ dưới ánh mặt trời trên hòn đảo giữa hồ, được xây dựng bao quanh tòa tháp ấy.',
    'STm10001_02.473': 'Một Cự Tháp trên hòn đảo giữa hồ...==W== và cả cách bố trí đường xá quen thuộc này nữa.',
    'STm10001_02.474': 'Chẳng lẽ đây là...==W== Philae sao?',
    'STm10001_02.476': 'Đó mới chính là Filanis thực sự.==W== Thành Phố Hoàn Hảo vĩ đại.',
    'STm10001_03.4': 'Hồi 3',
    'STm10001_03.5': 'Nhà Tắm và Nô Lệ',
    'STm10001_03.6': 'Tại nhà tắm công cộng, bạn nghe kể rằng Olympia đã giải phóng toàn bộ nô lệ trong thành phố. Cải trang thành một nô lệ, Elis thăm dò được một lối tẩu thoát qua đường cống ngầm. Trước khi bạn kịp tìm cách trốn thoát, Alina bất ngờ cất lời hỏi bạn về thuật hồi sinh.',
    'STm10001_03.42': 'Chúng ta tới nơi rồi, thưa ==SEX12== Tu Giả. Chào mừng ngài đến với Nhà Tắm Olympia, được đặt tên nhằm tôn vinh Chấp Chính Quan.',
    'STm10001_03.57': 'Đây là nhân viên phục vụ của chúng tôi, Lulu. Cô ấy sẽ đáp ứng mọi nhu cầu của ngài.',
    'STm10001_03.63': 'Nhân Viên Nhà Tắm',
    'STm10001_03.74': 'Rất hân hạnh được đón tiếp hai vị. Nguyện xin Thần Ma Pháp luôn che chở cho cả hai.',
    'STm10001_03.80': 'Hôm nay nắng ở Filanis gay gắt lắm. Mời hai vị dùng thử món trà mật ong ướp lạnh đặc sản của quán chúng tôi. Nó sẽ giúp hai vị giải nhiệt nhanh chóng đấy ạ.',
    'STm10001_03.83': 'Và đây là khăn vải lanh ướp hương hoa cúc để hai vị lau tay.',
    'STm10001_03.100': 'Cô ấy còn chưa dứt lời, những cánh tay bóng ma đen tuyền đã lập tức hiện hình xung quanh chúng tôi.==W== Chúng nâng những chiếc cốc đất nung và khăn lau, dâng lên với sự chuẩn xác đến rợn người.',
    'STm10001_03.112': 'Đây là... ma pháp ư?',
    'STm10001_03.118': 'Hì hì, mong là cảnh tượng vừa rồi không làm hai vị giật mình. Tạo hình ma lực thành các chi thể là sở trường của em đấy ạ. Nhờ vậy mà một mình em có thể gánh vác công việc của cả một dàn người hầu.',
    'STm10001_03.123': 'Ái chà, xin thứ lỗi cho em. Mải tíu tít quá nên em quên mất chưa hỏi quý danh của hai vị.',
    'STm10001_03.129': 'Đây là chủ nhân của tôi, Tu Giả ==PLAYER_NAME==. Còn tôi là nô lệ hầu cận của ==SEX3==, Elis.',
    'STm10001_03.133': 'Chủ nhân...?==W== Nô lệ...?==W== Đội trưởng Alina, khoan đã! Sao lại có nô lệ ở đây thế này?',
    'STm10001_03.146': 'Ở đây cấm nô lệ sao? Ngay cả ở Emor, chủ nhân đi đâu thì nô lệ cũng phải theo đó phục dịch mà.',
    'STm10001_03.148': 'Lulu, họ không phải người ở Filanis. Trường hợp này hơi đặc biệt. Em đi chuẩn bị bồn tắm đi, ở đây cứ để chị lo.',
    'STm10001_03.151': 'V-Vâng ạ...',
    'STm10001_03.160': '<size=35>Trông đạo mạo đàng hoàng thế kia mà vẫn còn nuôi nô lệ. Đúng là thứ ký sinh trùng ghê tởm.',
    'STm10001_03.163': 'Này! Cô vừa nói cái gì đấy? Ăn nói cho cẩn thận trước mặt Chủ nhân của tôi đấy nhé!',
    'STm10001_03.169': 'Tôi thay mặt Lulu tạ lỗi với ngài. Vì quá khứ của bản thân, con bé không thể nào chịu đựng nổi những kẻ sở hữu nô lệ.',
    'STm10001_03.171': 'Thứ lỗi cho tôi hỏi nhé? Mọi gia đình ở Nova đều nuôi nô lệ mà. Đừng bảo với tôi là ở Filanis chẳng có lấy một mống nào đấy nhé?',
    'STm10001_03.173': 'Trước đây thì có. Nhưng giờ thì không còn nữa rồi.',
    'STm10001_03.178': 'Nhiều năm trước, người đứng đầu của chúng tôi, Chấp Chính Quan Olympia, đã trả tự do cho tất cả nô lệ trong thành phố==RT==và ban cho họ quyền công dân đầy đủ.',
    'STm10001_03.181': 'Kể từ đó, chúng tôi chỉ gắn kết với nhau bằng thiện chí và tình đồng chí hữu nghị.==RT==Chính nhờ vậy mà Filanis mới hưng thịnh trở thành Thành Phố Hoàn Hảo như ngày hôm nay.',
    'STm10001_03.183': 'G-Giải phóng toàn bộ bọn họ sao? Thế thì ai làm những công việc nặng nhọc tay chân?',
    'STm10001_03.184': 'Chấp Chính Quan Olympia đã chế tạo ra những con rối ma pháp. Chúng đảm nhiệm toàn bộ công việc nặng nhọc mà trước đây nô lệ từng phải làm.',
    'STm10001_03.186': 'Những con rối ư? Khoan đã, chẳng lẽ những thứ trong khu rừng lúc nãy...',
    'STm10001_03.208': 'Đúng vậy, đó chính là những con rối bị bỏ hoang của Filanis.',
    'STm10001_03.210': 'Chúng được đẽo gọt từ gỗ. Nếu không có ma lực truyền vào, chúng chẳng khác gì những con rối bình thường cả.',
    'STm10001_03.211': 'Người dân thường để lại những con rối đã hỏng trong rừng để chúng tự phân hủy về với tự nhiên. Tôi vẫn đang điều tra xem tại sao đám rối lúc nãy lại tự động cử động và tấn công chúng ta.',
    'STm10001_03.213': 'Thời gian không còn nhiều nữa. Xin ngài hãy tắm rửa nhanh lên. Giờ diện kiến Chấp Chính Quan Olympia sắp đến rồi.',
    'STm10001_03.215': 'Nếu ngài còn thắc mắc gì về Filanis, sau buổi diện kiến chúng ta có thể thong thả đàm đạo tiếp.',
    'STm10001_03.217': 'Alina, cảm ơn cô vì đã sắp xếp chu đáo mọi chuyện thế này. Có cách nào để tôi đền đáp cô không?',
    'STm10001_03.223': '(Với cô nàng Dạ Hành Giả kia cũng thế. Bỏ cái vẻ lịch thiệp nhã nhặn ấy đi, diễn thế lộ liễu lắm. Nhưng nếu cô ta phục vụ chu đáo, hãy ban thưởng cho cô ta thật hậu hĩnh.)',
    'STm10001_03.227': 'Elis bảo mình phải tỏ ra có quyền uy. Hy vọng vừa rồi nghe không bị gượng gạo quá.',
    'STm10001_03.229': 'Đó là bổn phận của tôi, thưa ==SEX12== Tu Giả.==W== Nhưng tôi quả thực có một thỉnh cầu. Nếu sau buổi diện kiến ngài còn chút thời gian rảnh, tôi muốn xin ngài chỉ giáo về một vấn đề ma pháp.',
    'STm10001_03.231': 'Được chứ.',
    'STm10001_03.271': 'Phù...==W== Đúng là thiên đường. Cuối cùng mình cũng cảm thấy như được sống lại.',
    'STm10001_03.275': 'Làn nước nóng khiến da thịt mình khoan khoái râm ran. Từng thớ cơ đang nhức mỏi đều được thả lỏng hoàn toàn.',
    'STm10001_03.279': 'Rốt cuộc đây là đâu?==W== Tại sao Elis và Alina trông lại quen thuộc đến thế? Mình phải nói gì với Chấp Chính Quan đây? Alina muốn xin lời khuyên về ma pháp, nhưng mình thì mù tịt ma thuật. Phải làm cách nào mới trở về được đây...',
    'STm10001_03.294': 'Những câu hỏi này...==W== lúc này mình chẳng muốn nghĩ ngợi gì thêm nữa. Mình chỉ muốn cứ ngâm mình lững lờ trôi thế này cho đến khi tan biến mà thôi.',
    'STm10001_03.296': 'Được rồi, không phải là mình không quan tâm đâu.==W== Chỉ là mình thực sự cần được nghỉ ngơi một chút lúc này.',
    'STm10001_03.301': 'Ồ, có thứ gì đó đang kỳ lưng cho mình. Cảm giác sảng khoái ghê gớm. Bồn tắm này có yểm sẵn ma pháp xoa bóp sao? Người Filanis đúng là biết hưởng thụ thật.',
    'STm10001_03.302': 'Khoan đã. Một nhà tắm mộc mạc thôn dã thế này làm sao có vòi phun xoa bóp được chứ?!',
    'STm10001_03.317': 'Hửm, hừm-hừm-hừm<size=52> ♪',
    'STm10001_03.319': 'E-Elis?! Cô đang làm cái trò gì thế hả?',
    'STm10001_03.322': 'Em đang kỳ lưng cho Chủ nhân mà.',
    'STm10001_03.323': 'Khoan đã! Cô chui vào đây từ lúc nào thế? Chẳng phải chúng ta được bố trí hai bồn tắm riêng biệt sao?',
    'STm10001_03.326': 'Ôi dào, Chủ nhân đừng có ngượng ngùng thế chứ. Làn da trắng trẻo và xương quai xanh quyến rũ thế kia cơ mà. Hãy tự tin lên!',
    'STm10001_03.327': 'Ôi dào, Chủ nhân đừng có ngượng ngùng thế chứ. Em đã quấn khăn tắm kín mít rồi, người sẽ không thấy điều gì bất nhã đâu. Còn vóc dáng hoàn hảo của người thì việc gì phải giấu giếm.',
    'STm10001_03.332': 'Dù sao thì chúng ta đều là con gái với nhau cả mà. Tắm chung một bồn thì có mất mát gì đâu chứ?',
    'STm10001_03.333': 'Dù sao thì anh cũng là đàn ông cơ mà. Mạnh mẽ lên xem nào!',
    'STm10001_03.336': 'Hơn nữa, em là nô lệ của người mà. Nô lệ tắm rửa kỳ lưng cho Chủ nhân chẳng phải là chuyện đương nhiên sao?',
    'STm10001_03.337': 'Đ-Đương nhiên cái nỗi gì? Chúng ta chỉ giả vờ làm chủ tớ để qua mắt người ngoài thôi. Tôi còn chẳng ưa nổi chế độ nô lệ, nói gì đến chuyện cần một người hầu.',
    'STm10001_03.338': 'Ồ? Chủ nhân ghét chế độ nô lệ chẳng khác nào dân bản xứ ở đây nhỉ. Sao lại thế?',
    'STm10001_03.339': 'Cớ sao một người lại có thể sở hữu một con người khác chứ? Cảm giác đó sai trái vô cùng. Tôi chẳng cần lý do nào to tát hơn thế cả.',
    'STm10001_03.340': 'Còn cô thì sao? Nếu cần một vỏ bọc, cô hoàn toàn có thể nhận làm bạn bè hay bạn đồng hành mà. Sao cứ nhất quyết phải làm nô lệ chứ?',
    'STm10001_03.343': 'Bởi vì làm thế rất thực tế. Anh bảo sở hữu người khác là sai trái. Nhưng lỡ như trong mắt người Nova, nô lệ ngay từ đầu vốn dĩ chẳng được coi là con người thì sao?',
    'STm10001_03.345': 'Không phải là người ư...',
    'STm10001_03.346': 'Hừm. Ở các khu chợ tại Emor, một con ngựa còn có giá đắt hơn nhiều so với một nô lệ. Đối với phần lớn người Nova, nô lệ chẳng qua chỉ là một món đồ vật không hơn không kém.',
    'STm10001_03.347': 'Và làm một món đồ vật thì lại có cái lợi của nó.',
    'STm10001_03.348': 'Lợi ích ở chỗ nào cơ chứ?',
    'STm10001_03.351': 'Chà, chẳng ai lại rỗi hơi đi soi mói một món đồ vật cả.==W== Và với em, đó chính là lợi thế lớn nhất.',
    'STm10001_03.352': 'Nếu em nhận là bạn đồng hành của anh, em sẽ phải bịa ra một lai lịch hoàn hảo không tì vết. Một vỏ bọc chắc chắn sẽ sụp đổ trước sự điều tra, nhất là khi em là một Thánh Nữ Sa Ngã đã trốn chui trốn nhủi trong tháp suốt ba năm.',
    'STm10001_03.353': 'Nhưng nếu là nô lệ? Em chỉ cần anh gật đầu một cái là xong. Mọi ánh mắt soi mói nghi ngờ sẽ đổ dồn hết lên người anh, bởi vì em chỉ đơn thuần là một món tài sản thuộc về anh mà thôi.',
    'STm10001_03.354': 'Này nhé. Cô tính toán đâu ra đấy thật đấy. Tôi chẳng biết cô là kẻ mưu mô xảo quyệt hay chỉ là kẻ liều mạng nữa.',
    'STm10001_03.355': 'Lỡ như tôi từ chối không chịu phối hợp thì sao? Hoặc lỡ tôi là kẻ nguy hiểm thì tính thế nào?',
    'STm10001_03.356': 'Lúc em tìm thấy thì anh chỉ là một cái xác không hồn, em việc gì phải sợ chứ.==W== Lúc anh tỉnh lại đúng là có làm em giật bắn mình thật, nhưng em đã quan sát anh rất kỹ trước khi quyết định tiếp tục diễn màn kịch này.',
    'STm10001_03.357': 'Anh hiền lành, nhân hậu, thông minh, lại còn hoàn toàn vô hại nữa.==W== Đúng là người tuyệt vời nhất mà em từng gặp luôn đó~',
    'STm10001_03.360': 'Haizz. Sao nghe lời khen đó chẳng khác nào một lời xúc phạm thế nhỉ?!',
    'STm10001_03.361': 'Thế nên đóng vai nô lệ của anh chẳng có chút rủi ro nào cả.==W== Em thậm chí còn dám cá là anh sẽ không bao giờ coi em như một món đồ vật đâu. Và em đã đúng.',
    'STm10001_03.362': 'Nhân tiện thì đây là lần đầu tiên em đóng vai nô lệ đấy nhé. Em diễn xuất sắc không tì vết đúng không nào? Lời khen ngợi của em đâu rồi?',
    'STm10001_03.365': 'Rồi rồi. Giỏi lắm.',
    'STm10001_03.366': 'Ít ra anh cũng phải giả vờ nói cho có tâm chút chứ!',
    'STm10001_03.368': 'Elis, cô lẻn vào bồn tắm của tôi không phải chỉ để buôn chuyện với làm nũng đấy chứ?',
    'STm10001_03.369': 'Haha, tại em nhập tâm vào vai diễn quá thôi. Suýt nữa thì quên mất chuyện chính.',
    'STm10001_03.370': 'Tắm xong chúng ta phải đi diện kiến Chấp Chính Quan rồi. Vở kịch này có thể qua mắt được một Dạ Hành Giả nơi thôn dã, nhưng tuyệt đối không thể lừa nổi Chấp Chính Quan đâu.',
    'STm10001_03.371': 'Thế chúng ta phải làm sao?',
    'STm10001_03.372': 'Chuồn thôi chứ còn sao nữa!',
    'STm10001_03.376': 'Chạy đằng trời. Những cánh tay ma pháp đen ngòm kia đang canh gác nghiêm ngặt mọi cửa ra vào và cửa sổ rồi. Nói là phục vụ, nhưng rõ ràng là giám sát.',
    'STm10001_03.378': 'Hí hí, lại thêm một đặc quyền của nô lệ này!==W== Lulu đúng là có theo dõi chúng ta thật,==W== nhưng ngay khi em bảo là em vào để "phục dịch Chủ nhân", mặt cô bé đỏ bừng lên rồi vội vã tránh đi vì quá ghê tởm.',
    'STm10001_03.381': 'Cô bé có thể căm thù những kẻ nuôi nô lệ, nhưng sâu thẳm trong lòng? Cô bé vẫn chỉ coi em là một món đồ chơi tình dục mà thôi.',
    'STm10001_03.385': 'Lúc này, chắc cô bé ngây thơ kia đang tưởng tượng ra đủ trò đồi bại mà chúng ta đang làm trong này rồi.==W== Có cho kẹo cô bé cũng chẳng dám nhìn trộm đâu.',
    'STm10001_03.388': 'Thủ đoạn của cô... thực dụng đến rợn người thật đấy.',
    'STm10001_03.389': 'Về điểm này cô ấy thực sự có nét giống Iris, nhưng Iris sẽ không bao giờ dám táo bạo đến mức này.==W== Em ấy chẳng bao giờ có thể dựng lên một lời nói dối tinh vi như vậy được.',
    'STm10001_03.390': 'Thực dụng thì có gì sai chứ? Huống hồ...==W== ngay cả khi còn là một Thánh Nữ, em cũng chỉ bị đối xử như…',
    'STm10001_03.392': 'Không có gì! Dù sao thì lúc lẻn sang đây em đã phát hiện ra một đường ống thoát nước thông ra bên ngoài rồi.',
    'STm10001_03.393': 'Anh cứ đi ra sảnh trước nói chuyện với Dạ Hành Giả đi. Chẳng phải cô ta có điều muốn thỉnh giáo anh sao?==W== Hãy tận dụng cơ hội đó để giữ chân cô ta.',
    'STm10001_03.395': 'Em sẽ chui qua cống ngầm rồi gây náo loạn ngoài đường phố. Một khi cô ta chạy đi kiểm tra, anh chỉ việc ung dung sải bước ra khỏi cửa chính thôi.',
    'STm10001_03.396': 'Kế hoạch hay đấy. Bên ngoài chỉ có mỗi Alina và Lulu. Nếu hai ta tách ra...==W== bọn họ chắc chắn sẽ ưu tiên đuổi theo vị Thánh Nữ Sa Ngã tình nghi trước.',
    'STm10001_03.397': 'Nhưng làm vậy chẳng phải cô sẽ biến thành mục tiêu công kích lớn nhất sao?',
    'STm10001_03.398': 'Đừng lo cho em, Chủ nhân. Ba năm trốn trong tòa tháp đó em ngày đêm miệt mài nghiên cứu ma pháp cơ mà.',
    'STm10001_03.403': 'Được rồi, mình đã mặc đồ xong xuôi. Giờ này chắc Elis đã chui vào đường cống ngầm rồi.',
    'STm10001_03.404': 'Giờ đến lượt Alina...==W== A, cô ấy ở đằng kia.',
    'STm10001_03.410': '<size=75>Hỡi Nữ Thần Trivia từ bi và toàn năng, xin hãy lắng nghe lời cầu nguyện của con.',
    'STm10001_03.412': '<size=75>Xin hãy đưa những người chị em đã ngã xuống của con về cõi trời cao,==RT==để họ được tung cánh bay lượn theo mười hai luồng gió.',
    'STm10001_03.413': 'Cô ấy đang... cầu nguyện trước Cự Tháp sao?',
    'STm10001_03.415': 'Ôi, thành thật xin lỗi ngài. Tôi mải cầu nguyện với Nữ Thần nên không để ý thấy ngài, thưa ==SEX12== Tu Giả.',
    'STm10001_03.416': 'Không sao đâu. Nhà tắm tuyệt vời lắm, bao nhiêu mệt mỏi đều tan biến hết cả.',
    'STm10001_03.417': 'Chẳng phải cô có chuyện muốn hỏi tôi sao? Chúng ta vẫn còn chút thời gian trước khi gặp Chấp Chính Quan. Cô cứ hỏi đi.',
    'STm10001_03.418': 'N-Ngay lúc này sao?==W== Nhưng mà...',
    'STm10001_03.419': 'Alina ngập ngừng, một điều hiếm thấy ở cô.==RT==Cô đưa mắt nhìn về phía Cự Tháp sừng sững hồi lâu,==RT==như thể đang tìm kiếm một lời chỉ dẫn từ định mệnh.',
    'STm10001_03.426': 'Cự Tháp vẫn chỉ đứng lặng thinh ở đó trong tĩnh lặng.==RT==Nó không đoái hoài đến những mối hoài nghi của người phàm,==RT==và hiển nhiên cũng chẳng đưa ra bất kỳ lời giải đáp nào.',
    'STm10001_03.428': 'Xin thứ lỗi vì đã để ngài phải đợi lâu, thưa ==SEX12== Tu Giả.',
    'STm10001_03.429': 'Câu hỏi của tôi có phần...==W== mạo phạm và vượt quá phận sự. Nếu có làm phật ý ngài, tôi xin được tạ lỗi trước.',
    'STm10001_03.430': 'Không sao đâu. Cô cứ nói đi.',
    'STm10001_03.432': 'Ngài có thể kể cho tôi nghe về <color=#3faeae>thuật hồi sinh</color> được không?',
    'STm10001_03.441': '<size=50>Ngài muốn trả giá bằng điều gì cũng được...==W== Tôi sẽ dâng cho ngài bất cứ thứ gì tôi có!',
}
